try{const data=JSON.parse(localStorage.getItem(SAVE)||'null');if(data?.version===2&&Number.isFinite(data.x)&&Number.isFinite(data.y))repairPosition(data);if(validState(data)){state=data;hasSave=true;}const p=JSON.parse(localStorage.getItem(PREFS)||'null');if(p){prefs={sound:p.sound===true,rain:p.rain!==false,fps:p.fps===true,zoom:[.8,1,1.2].includes(p.zoom)?p.zoom:1};}}catch{storageOK=false;}
const dialogs=['inventory','loot','pause','settings','complete'];const blocked=()=>dialogs.some(id=>$(id).open);function resetInput(){joy={x:0,y:0};keys.clear();$('joy-knob').style.transform='translate(0,0)';}
