function setMenu(){resetInput();mode='menu';$('menu').hidden=false;$('play').hidden=true;closeAll();$('continue').hidden=!hasSave;$('continue-info').textContent=state.completed?'ПЕРВЫЙ СИГНАЛ ПОЛУЧЕН · ПОСМОТРЕТЬ ЛОКАЦИЮ':'СЕКТОР 07 · ПРОГРЕСС СОХРАНЁН';updateAudio();}
