$('continue').onclick=()=>start();$('new-game').onclick=()=>{if(hasSave&&!window.confirm('Начать новую вылазку? Текущее сохранение этой версии будет заменено.'))return;start(true);};$('settings-open').onclick=()=>openPanel('settings');$('pause-button').onclick=()=>openPanel('pause');$('resume').onclick=()=>$('pause').close();$('back-menu').onclick=()=>{persist();setMenu();};$('pause-settings').onclick=()=>openPanel('settings');
const audioState={context:null,rain:null,gain:null};function ensureAudio(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return false;audioState.context??=new A();audioState.context.resume();if(!audioState.rain){const a=audioState.context,b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*.12;const source=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();source.buffer=b;source.loop=true;f.type='lowpass';f.frequency.value=2200;g.gain.value=0;source.connect(f).connect(g).connect(a.destination);source.start();audioState.rain=source;audioState.gain=g;}return true;}catch{return false;}}
function updateAudio(){if(audioState.gain)audioState.gain.gain.value=prefs.sound&&mode==='play'?.15:0;}
function beep(freq=180,duration=.08,volume=.02){const a=audioState.context;if(!prefs.sound||!a)return;const o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(volume,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+duration);}
$('sound-toggle').checked=prefs.sound;$('rain-toggle').checked=prefs.rain;$('fps-toggle').checked=prefs.fps;$('zoom-select').value=String(prefs.zoom);
$('sound-toggle').onchange=()=>{prefs.sound=$('sound-toggle').checked;if(prefs.sound&&!ensureAudio()){prefs.sound=false;$('sound-toggle').checked=false;notify('Звук недоступен в этом браузере.');}updateAudio();storePrefs();};$('rain-toggle').onchange=()=>{prefs.rain=$('rain-toggle').checked;storePrefs();};$('fps-toggle').onchange=()=>{prefs.fps=$('fps-toggle').checked;$('fps').hidden=!prefs.fps;storePrefs();};$('zoom-select').onchange=()=>{prefs.zoom=Number($('zoom-select').value);resize();storePrefs();};
function iconPath(id){return 'assets/items/'+id+'.png';}function slot(id,count,handler,{active=false,equipped=false}={}){const b=document.createElement(handler?'button':'div');b.className='item-slot'+(!id?' empty':'')+(active?' selected':'')+(equipped?' equipped':'');if(id){if(handler)b.setAttribute('aria-label',ITEMS[id].name+', '+count);const img=document.createElement('img');img.src=iconPath(id);img.alt=ITEMS[id].name;b.append(img);if(count>1){const n=document.createElement('span');n.textContent=count;b.append(n);}if(handler)b.onclick=handler;}else if(handler)b.disabled=true;return b;}
function fillGrid(el,entries,min,onSelect,selectedId){el.replaceChildren();entries.forEach(([id,n])=>el.append(slot(id,n,onSelect?()=>onSelect(id):null,{active:selectedId===id,equipped:id==='backpack'&&state.backpack})));for(let i=entries.length;i<min;i++)el.append(slot(null,0));}
function renderInventory(){const entries=Object.entries(state.inventory),quick=entries.filter(([id])=>['bandage','water','food','flashlight','radio'].includes(id)).slice(0,6),rest=entries.filter(([id])=>!quick.some(([q])=>q===id));fillGrid($('pockets'),quick,6,selectItem,selected);fillGrid($('bag-grid'),rest,18,selectItem,selected);$('equipment-slots').replaceChildren();for(const id of ['jacket','vest','boots','backpack'])$('equipment-slots').append(slot(id,1,()=>selectItem(id),{active:selected===id,equipped:id!=='backpack'||state.backpack}));$('capacity-label').textContent=state.backpack?'ПОЛЕВОЙ · 30 КГ':'ВЕЩМЕШОК · 18 КГ';$('inventory-weight').textContent=formatWeight(weight(state))+' / '+capacity(state)+' КГ';$('weight-bar').style.width=Math.min(100,weight(state)/capacity(state)*100)+'%';selectItem(selected,false);}
function selectItem(id,redraw=true){selected=id;const item=ITEMS[id];$('detail-icon').src=iconPath(id);$('detail-icon').alt=item.name;$('detail-title').textContent=item.name;$('detail-desc').textContent=item.desc;$('detail-meta').textContent=(item.condition?'Состояние '+item.condition+'% · ':'')+formatWeight(item.weight)+' кг';const owned=!!state.inventory[id];$('use-item').disabled=!owned||!['consume','equip'].includes(item.type)||(id==='backpack'&&state.backpack);$('use-item').textContent=id==='backpack'?(state.backpack?'НАДЕТ':'НАДЕТЬ'):item.type==='consume'?'ИСПОЛЬЗОВАТЬ':item.type==='clothes'?'НАДЕТО':'В РЮКЗАКЕ';if(redraw)renderInventory();}
$('inventory-button').onclick=()=>{selected=state.inventory.radio?'radio':Object.keys(state.inventory)[0]||'jacket';renderInventory();openPanel('inventory');};$('use-item').onclick=()=>{if(use(state,selected)){beep(260,.1);persist();updateHUD();if(!state.inventory[selected])selected=Object.keys(state.inventory)[0]||'jacket';renderInventory();}else notify('Сейчас этот предмет не нужен.');};
function renderLoot(){const remaining=state.remaining[activeContainer];const entries=Object.entries(remaining);if(!remaining[lootSelected])lootSelected=entries[0]?.[0]||null;$('loot-title').textContent=CONTAINERS.find(c=>c.id===activeContainer).name;$('loot-count').textContent=entries.reduce((s,[,n])=>s+n,0)+' ПРЕДМ.';$('loot-weight').textContent=formatWeight(weight(state))+' / '+capacity(state)+' КГ';fillGrid($('found-grid'),entries,8,id=>{lootSelected=id;renderLoot();},lootSelected);fillGrid($('carried-grid'),Object.entries(state.inventory),8,null,null);$('take-item').disabled=!lootSelected;$('take-all').disabled=!entries.length;const item=ITEMS[lootSelected];$('loot-detail-icon').hidden=!item;if(item){$('loot-detail-icon').src=iconPath(lootSelected);$('loot-detail-icon').alt=item.name;$('loot-detail-title').textContent=item.name;$('loot-rarity').textContent=item.rarity;$('loot-rarity').style.color=item.type==='quest'?'#76a8b4':'#9da98c';$('loot-detail-desc').textContent=item.desc;$('loot-detail-meta').textContent=(item.condition?'Состояние '+item.condition+'% · ':'')+formatWeight(item.weight)+' кг';}else{$('loot-detail-title').textContent='ЗДЕСЬ БОЛЬШЕ НИЧЕГО НЕТ';$('loot-rarity').textContent='';$('loot-detail-desc').textContent='Всё найденное теперь в твоём рюкзаке.';$('loot-detail-meta').textContent='';}}
function acquire(id){const result=take(state,activeContainer,id);if(!result.ok){notify(result.reason);return false;}if(id==='radio'){radioUntil=t+7;$('radio-message').hidden=false;beep(380,.25);}else beep(230,.06);persist();updateHUD();return true;}
$('take-item').onclick=()=>{if(lootSelected)acquire(lootSelected);renderLoot();};$('take-all').onclick=()=>{for(const [id,n] of Object.entries({...state.remaining[activeContainer]}))for(let k=0;k<n;k++)if(!acquire(id))break;renderLoot();};
function doAction(){if(mode!=='play'||blocked())return;const target=nearby(state);if(!target)return;resetInput();if(target.id==='enter'||target.id==='leave'){portal(state,target.id);persist();updateHUD();beep(110,.14);return;}if(target.id==='exit'){if(complete(state)){persist();$('result-loot').textContent='В РЮКЗАКЕ: '+Object.values(state.inventory).reduce((a,b)=>a+b,0)+' ПРЕДМЕТОВ';$('result-save').textContent=storageOK?'✓ Прогресс сохранён на этом устройстве':'Сохранение недоступно. Не закрывай страницу.';openPanel('complete');beep(440,.3);}return;}activeContainer=target.id;lootSelected=null;renderLoot();openPanel('loot');}
$('action-button').onclick=doAction;$('finish-button').onclick=()=>{persist();setMenu();};
function formatWeight(n){return n.toFixed(1).replace('.',',');}
function updateHUD(){for(const stat of ['health','water','food'])$(stat+'-bar').style.width=state[stat]+'%';$('bag-weight').textContent=formatWeight(weight(state))+' кг';const n=nearby(state);$('action-button').disabled=!n;$('action-label').textContent=n?.id==='enter'?'ВОЙТИ':n?.id==='leave'?'ВЫЙТИ':n?.id==='exit'?'ВЕРНУТЬСЯ':'ОБЫСКАТЬ';$('near-label').hidden=!n;$('near-label').textContent=n?.name||'';$('mission-text').textContent=state.completed?'Первый сигнал получен. Можно исследовать участок.':state.inventory.radio?'Донеси рацию к воротам во дворе.':state.inside?'Обыщи шкаф в кабинете справа.':'Войди в поликлинику через главный вход.';const minutes=40+Math.floor(state.elapsed/15);$('clock').textContent='07:'+String(minutes%60).padStart(2,'0');}
const joystick=$('joystick');let joyPointer=null;function joyMove(e){if(e.pointerId!==joyPointer)return;const box=joystick.getBoundingClientRect(),radius=box.width*.32;let x=e.clientX-box.left-box.width/2,y=e.clientY-box.top-box.height/2;const length=Math.hypot(x,y);if(length>radius){x=x/length*radius;y=y/length*radius;}joy={x:x/radius,y:y/radius};$('joy-knob').style.transform=`translate(${x}px,${y}px)`;}
joystick.addEventListener('pointerdown',e=>{if(mode!=='play'||blocked())return;e.preventDefault();joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);joyMove(e);if(prefs.sound){ensureAudio();updateAudio();}});joystick.addEventListener('pointermove',joyMove);for(const event of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(event,e=>{if(e.pointerId===joyPointer){joyPointer=null;resetInput();}});
const KEYMAP={a:'left',ф:'left',arrowleft:'left',d:'right',в:'right',arrowright:'right',w:'up',ц:'up',arrowup:'up',s:'down',ы:'down',arrowdown:'down'};
window.addEventListener('keydown',e=>{if(mode!=='play')return;const k=e.key.toLowerCase();if(k==='escape'){if($('settings').open)$('settings').close();else if($('inventory').open)$('inventory').close();else if($('loot').open)$('loot').close();else if($('pause').open)$('pause').close();else if(!$('complete').open)openPanel('pause');return;}if(blocked())return;if(KEYMAP[k]){e.preventDefault();keys.add(KEYMAP[k]);}if(['e','у',' '].includes(k)){e.preventDefault();if(!e.repeat)doAction();}if(['i','ш','tab'].includes(k)){e.preventDefault();$('inventory-button').click();}});window.addEventListener('keyup',e=>{if(KEYMAP[e.key.toLowerCase()])keys.delete(KEYMAP[e.key.toLowerCase()]);});
window.addEventListener('blur',()=>{resetInput();if(mode==='play'&&!blocked())openPanel('pause');persist();});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetInput();persist();if(mode==='play'&&!blocked())openPanel('pause');}});for(const id of dialogs)$(id).addEventListener('close',()=>{resetInput();persist();});
function resize(){const w=window.innerWidth,h=window.innerHeight;const dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ratio=w/h;cam.h=Math.min(WORLD.height,(ratio<1?900:650)/prefs.zoom);cam.w=cam.h*ratio;if(cam.w>WORLD.width){cam.w=WORLD.width;cam.h=cam.w/ratio;}ctx.imageSmoothingEnabled=false;}
window.addEventListener('resize',resize);
function draw(){const sw=canvas.width,sh=canvas.height;cam.x=Math.max(0,Math.min(WORLD.width-cam.w,state.x-cam.w*.5));cam.y=Math.max(0,Math.min(WORLD.height-cam.h,state.y-cam.h*.55));const scale=sw/cam.w;ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#17231a';ctx.fillRect(0,0,sw,sh);ctx.setTransform(scale,0,0,scale,-cam.x*scale,-cam.y*scale);ctx.drawImage(assets.map,0,0,WORLD.width,WORLD.height);
 // Interaction glints are small world-space cues, not minimap markers.
 const targets=CONTAINERS.filter(c=>c.inside===state.inside&&Object.keys(state.remaining[c.id]).length);if(!state.inside)targets.push({id:'enter',x:929,y:682});if(!state.inside&&state.inventory.radio&&!state.completed)targets.push({id:'exit',x:854,y:755});for(const obj of targets){const d=Math.hypot(state.x-obj.x,state.y-obj.y);if(d<240){const a=.35+.25*Math.sin(t*3);ctx.strokeStyle=`rgba(204,220,169,${a})`;ctx.lineWidth=1.3;ctx.beginPath();ctx.ellipse(obj.x,obj.y+5,13,5,0,0,Math.PI*2);ctx.stroke();if(obj.id!=='enter'&&obj.id!=='exit'){ctx.fillStyle='#d7deb3';ctx.fillRect(obj.x-1,obj.y-8,2,3);}}}
 const phase=walking?[0,1,0,2][Math.floor(walkPhase*9)%4]:0;const sprite=assets[state.direction+'-'+phase];const heroHeight=48,heroWidth=heroHeight*128/176;ctx.fillStyle='#06110b77';ctx.beginPath();ctx.ellipse(state.x,state.y+1,13,4,0,0,Math.PI*2);ctx.fill();ctx.drawImage(sprite,Math.round(state.x-heroWidth/2),Math.round(state.y-heroHeight+2),heroWidth,heroHeight);drawForeground(ctx,assets.map,state.x,state.y,heroHeight);ctx.setTransform(1,0,0,1,0,0);
 if(prefs.rain&&!state.inside){ctx.strokeStyle='#c4d9cf2b';ctx.lineWidth=.8;ctx.beginPath();for(let i=0;i<65;i++){const x=((i*139.3-t*38)%sw+sw)%sw,y=(i*79.7+t*165)%sh;ctx.moveTo(x,y);ctx.lineTo(x-4,y+12);}ctx.stroke();}}
function frame(ms){const rawDt=last?Math.max(0,(ms-last)/1000):0;const dt=Math.min(rawDt,.05);last=ms;t+=dt;if(mode==='play'&&ready){walking=false;if(!blocked()){state.elapsed+=dt;const dx=joy.x+Number(keys.has('right'))-Number(keys.has('left')),dy=joy.y+Number(keys.has('down'))-Number(keys.has('up'));const beforeX=state.x,beforeY=state.y;walking=move(state,dx,dy,dt);const travelled=Math.hypot(state.x-beforeX,state.y-beforeY);if(walking){walkPhase+=travelled/104;if(walkPhase-footAt>.39){footAt=walkPhase;beep(state.inside?75:55,.045,.012);}}if(t-saveAt>2){persist();saveAt=t;}updateHUD();}draw();$('guide').hidden=t>guideUntil||blocked();if(t>noticeUntil)$('notification').hidden=true;if(t>radioUntil)$('radio-message').hidden=true;$('fps').hidden=!prefs.fps;frameCount++;frameTime+=rawDt;if(frameTime>.7){$('fps').textContent=Math.round(frameCount/frameTime)+' FPS';frameCount=0;frameTime=0;}}requestAnimationFrame(frame);}
async function preload(){const files={map:'assets/clinic-v2.webp'};for(const dir of ['south','west','east','north'])for(let f=0;f<3;f++)files[dir+'-'+f]='assets/hero/'+dir+'-'+f+'.png';let count=0;try{await Promise.all(Object.entries(files).map(([key,url])=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{assets[key]=img;$('load-progress').style.width=(++count/Object.keys(files).length*100)+'%';resolve();};img.onerror=()=>reject(new Error(url));img.src=url;})));ready=true;$('loading').hidden=true;resize();setMenu();}catch(error){$('loading-label').textContent='НЕ УДАЛОСЬ ЗАГРУЗИТЬ ГРАФИКУ. НАЖМИ, ЧТОБЫ ПОВТОРИТЬ.';$('loading').onclick=()=>{location.reload();};console.error('Asset load failed:',error.message);}}
